<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function mon(float $n,string $c):string{return ($c==='USD'?'US$ ':'$ ').number_format($n,2,',','.');}
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$quotes=$db->query("SELECT q.*,p.project_number,p.name project_name,c.business_name,(SELECT COUNT(*) FROM quote_items qi WHERE qi.quote_id=q.id) item_count FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id ORDER BY q.quote_date DESC,q.id DESC")->fetchAll();$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuestos · Punto ERP</title><style>:root{--o:#ff6702;--dark:#171b20;--ink:#27303b;--muted:#6e7781;--line:#e1e5e9;--bg:#f4f6f8;--sidebar:270px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.sidebar{position:fixed;inset:0 auto 0 0;width:var(--sidebar);padding:28px 18px;background:var(--dark);color:#fff}.brand{font-size:22px;font-weight:800;padding:0 12px 28px;border-bottom:1px solid #ffffff18}.brand i{color:var(--o);font-style:normal}.nav{display:flex;flex-direction:column;gap:5px;padding:24px 0}.nav a{padding:11px 13px;border-radius:9px;color:#d8dde3;text-decoration:none;font-weight:600}.nav a.active{background:var(--o);color:#fff}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.row{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.btn{display:inline-block;border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:700}.btn.gray{background:#edf0f3;color:#27303b}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line)}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.pill{display:inline-block;padding:4px 8px;border-radius:20px;background:#edf0f3;font-size:12px}.flash{padding:12px 15px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}@media(max-width:900px){.sidebar{position:static;width:auto}.main{margin-left:0;padding:22px 18px}}</style></head><body><aside class="sidebar"><div class="brand"><i>●</i> Punto ERP</div><nav class="nav"><a href="index.php">Panel general</a><a href="?a=clients">Clientes</a><a href="?a=partners">Arquitectos y constructoras</a><a href="?a=products">Productos</a><a href="?a=projects">Proyectos</a><a class="active" href="?a=quotes">Presupuestos</a><a href="?a=receipts">Recibos y pagos</a><?php if(($_SESSION['user']['role']??'')==='admin'):?><a href="?a=users">Perfiles y usuarios</a><?php endif;?></nav></aside><main class="main"><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><div class="row"><div><h1>Presupuestos</h1><p class="muted">Creá presupuestos dentro del sistema seleccionando cliente, proyecto y productos del catálogo.</p></div><a class="btn" href="?a=new_quote">+ Nuevo presupuesto</a></div><div class="card"><div style="overflow:auto"><table><thead><tr><th>Fecha</th><th>Cliente</th><th>Proyecto</th><th>Versión</th><th>Plantilla</th><th>Productos</th><th>Estado</th><th>Total</th><th></th></tr></thead><tbody><?php if(!$quotes):?><tr><td colspan="9" class="muted">Todavía no hay presupuestos.</td></tr><?php endif;?><?php foreach($quotes as $q):$legacy=(int)$q['item_count']===0;?><tr><td><?=e(date('d/m/Y',strtotime($q['quote_date'])))?></td><td><?=e($q['business_name'])?></td><td><?=e($q['project_number'].' · '.$q['project_name'])?></td><td>v<?=e($q['version_no'])?></td><td><?=e($q['quote_template_family']??($q['quote_families']??'—'))?></td><td><?=$legacy?'<span class="pill">Formato anterior</span>':e((string)$q['item_count'])?></td><td><?=e($q['status'])?></td><td><?=e(mon((float)$q['total'],$q['currency']??'ARS'))?></td><td><?php if(!$legacy):?><a class="btn gray" href="?a=quote_view&id=<?=$q['id']?>">Ver</a><?php else:?><a class="btn gray" href="?a=project&id=<?=$q['project_id']?>">Abrir proyecto</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
